288	                    fontFamily: FONT.sans,
289	                    fontSize: 13,
290	                    fontWeight: 400,
291	                    color: isDark ? BRAND.stoneLight : BRAND.stone,
292	                  } as React.CSSProperties}
293	                >
294	                  {s.label}
295	                </div>
296	              </div>
297	            ))}
298	          </motion.div>
299	        )}
300	      </div>
301	    </section>
