1	import { BRAND } from "@/lib/brand";
2	
3	interface TriCircleMarkProps {
4	  size?: number;
5	  opacity?: number;
6	}
7	
8	export function TriCircleMark({ size = 64, opacity = 1 }: TriCircleMarkProps) {
9	  const w = size;
10	  const h = size * 0.92;
11	  return (
12	    <svg
13	      width={w} height={h} viewBox="0 0 64 59"
14	      xmlns="http://www.w3.org/2000/svg"
15	      style={{ opacity }}
16	      aria-hidden="true"
17	    >
18	      <path
19	        d="M 30 0 a 30 30 0 0 0 -30 30 v -30 z"
20	        fill={BRAND.rust}
21	        transform="rotate(180 15 15)"
22	      />
23	      <path
24	        d="M 34 0 v 30 a 30 30 0 0 0 30 -30 z"
25	        fill={BRAND.amber}
26	        transform="rotate(180 49 15)"
27	      />
28	      <path
29	        d="M 17 30 a 15 15 0 1 0 30 0 a 15 15 0 1 0 -30 0 z"
30	        fill={BRAND.sage}
31	      />
32	    </svg>
33	  );
34	}
35	
36	export function TriCircleMarkV2({ size = 80, opacity = 1 }: TriCircleMarkProps) {
37	  const r = size * 0.28;
38	  const cx1 = size * 0.32;
39	  const cy1 = size * 0.32;
40	  const cx2 = size * 0.68;
41	  const cy2 = size * 0.32;
42	  const cx3 = size * 0.50;
43	  const cy3 = size * 0.68;
44	
45	  return (
46	    <svg
47	      width={size} height={size} viewBox={`0 0 ${size} ${size}`}
48	      xmlns="http://www.w3.org/2000/svg"
49	      style={{ opacity }}
50	      aria-hidden="true"
51	    >
52	      <circle cx={cx1} cy={cy1} r={r} fill={BRAND.rust} fillOpacity="0.92" />
53	      <circle cx={cx2} cy={cy2} r={r} fill={BRAND.amber} fillOpacity="0.92" />
54	      <circle cx={cx3} cy={cy3} r={r} fill={BRAND.sage} fillOpacity="0.92" />
55	    </svg>
56	  );
57	}
